	@Test
	void delegatesAcceptedDeclinedClosedUnsupportedAndFailure() {
		List<CloseableIteration<BindingSet>> wrappers = new ArrayList<>();
		try {
			RecordingIteration accepted = new RecordingIteration(true, null);
			CloseableIteration<BindingSet> acceptingWrapper = wrapper(accepted);
			wrappers.add(acceptingWrapper);
			CooperativeCancellation acceptingCancellation = assertInstanceOf(CooperativeCancellation.class,
					acceptingWrapper);
			assertTrue(acceptingCancellation.requestCancellation());
			assertEquals(1, accepted.requestCount.get());

			RecordingIteration declined = new RecordingIteration(false, null);
			CloseableIteration<BindingSet> decliningWrapper = wrapper(declined);
			wrappers.add(decliningWrapper);
			CooperativeCancellation decliningCancellation = assertInstanceOf(CooperativeCancellation.class,
					decliningWrapper);
			assertFalse(decliningCancellation.requestCancellation());
			assertEquals(1, declined.requestCount.get());

			CloseableIteration<BindingSet> unsupportedWrapper = wrapper(new EmptyIteration<>());
			wrappers.add(unsupportedWrapper);
			CooperativeCancellation unsupportedCancellation = assertInstanceOf(CooperativeCancellation.class,
					unsupportedWrapper);
			assertFalse(unsupportedCancellation.requestCancellation());

			RecordingIteration explicitlyClosed = new RecordingIteration(true, null);
			CloseableIteration<BindingSet> closedWrapper = wrapper(explicitlyClosed);
			wrappers.add(closedWrapper);
			closedWrapper.close();
			CooperativeCancellation closedCancellation = assertInstanceOf(CooperativeCancellation.class, closedWrapper);
			assertFalse(closedCancellation.requestCancellation());
			assertEquals(0, explicitlyClosed.requestCount.get(),
					"an explicitly closed wrapper must not call downstream cancellation");

			RecordingIteration exhausted = new RecordingIteration(true, null);
			CloseableIteration<BindingSet> exhaustedWrapper = wrapper(exhausted);
			wrappers.add(exhaustedWrapper);
			assertFalse(exhaustedWrapper.hasNext());
			CooperativeCancellation exhaustedCancellation = assertInstanceOf(CooperativeCancellation.class,
					exhaustedWrapper);
			assertFalse(exhaustedCancellation.requestCancellation());
			assertEquals(0, exhausted.requestCount.get(),
					"an exhausted wrapper must not call downstream cancellation");

			RuntimeException failure = new RuntimeException("cooperative cancellation failed");
			CloseableIteration<BindingSet> failingWrapper = wrapper(new RecordingIteration(true, failure));
			wrappers.add(failingWrapper);
			CooperativeCancellation failingCancellation = assertInstanceOf(CooperativeCancellation.class,
					failingWrapper);
			assertSame(failure, assertThrows(RuntimeException.class, failingCancellation::requestCancellation));
		} finally {
			wrappers.forEach(CloseableIteration::close);
		}
	}

