	@Test
	void nativeStateFactoryCanFinishAfterConcurrentCloseWithoutHoldingMapLock() throws Exception {
		NativeExecutionContext context = new NativeExecutionContext();
		CountDownLatch factoryEntered = new CountDownLatch(1);
		CountDownLatch closeEntered = new CountDownLatch(1);
		AtomicInteger stateCloses = new AtomicInteger();
		AtomicReference<Throwable> creatorFailure = new AtomicReference<>();
		Object key = new StateKey(1);

		Thread creator = new Thread(() -> {
			try {
				context.nativeState(key, () -> {
					factoryEntered.countDown();
					try {
						if (!closeEntered.await(5, TimeUnit.SECONDS)) {
							throw new AssertionError("close did not enter while native state was being created");
						}
					} catch (InterruptedException e) {
						Thread.currentThread().interrupt();
						throw new AssertionError(e);
					}
					context.installQueryScopedValueRegistrar(value -> {
					});
					return (AutoCloseable) stateCloses::incrementAndGet;
				});
			} catch (Throwable failure) {
				creatorFailure.set(failure);
			}
		}, "native-state-creator");
		creator.setDaemon(true);
		creator.start();
		assertTrue(factoryEntered.await(5, TimeUnit.SECONDS));

		Thread closer = new Thread(() -> {
			synchronized (context) {
				closeEntered.countDown();
				context.close();
			}
		}, "native-state-closer");
		closer.setDaemon(true);
		closer.start();

		creator.join(1_000);
		closer.join(1_000);
		assertFalse(creator.isAlive(), "state factory and close must not deadlock through shared cache locks");
		assertFalse(closer.isAlive(), "close must complete while state creation is paused");
		assertTrue(context.isClosed());
		assertEquals(1, stateCloses.get(), "a state created after close must be released exactly once");
		assertInstanceOf(IllegalStateException.class, creatorFailure.get());
	}

