	@Test
	void nativeStateSharesConcurrentSuccessfulInitialization() throws Exception {
		NativeExecutionContext context = new NativeExecutionContext();
		CountDownLatch factoryEntered = new CountDownLatch(1);
		CountDownLatch releaseFactory = new CountDownLatch(1);
		CountDownLatch waiterStarted = new CountDownLatch(1);
		AtomicInteger factoryCalls = new AtomicInteger();
		AtomicReference<Object> first = new AtomicReference<>();
		AtomicReference<Object> second = new AtomicReference<>();
		AtomicReference<Throwable> failure = new AtomicReference<>();
		Object expected = new Object();
		StateKey key = new StateKey(11);

		Thread creator = new Thread(() -> {
			try {
				first.set(context.nativeState(key, () -> {
					factoryCalls.incrementAndGet();
					factoryEntered.countDown();
					try {
						if (!releaseFactory.await(5, TimeUnit.SECONDS)) {
							throw new AssertionError("test did not release the native state factory");
						}
					} catch (InterruptedException e) {
						Thread.currentThread().interrupt();
						throw new AssertionError(e);
					}
					return expected;
				}));
			} catch (Throwable throwable) {
				failure.compareAndSet(null, throwable);
			}
		}, "native-state-success-creator");
		Thread waiter = new Thread(() -> {
			try {
				waiterStarted.countDown();
				second.set(context.nativeState(key, Object::new));
			} catch (Throwable throwable) {
				failure.compareAndSet(null, throwable);
			}
		}, "native-state-success-waiter");
		creator.setDaemon(true);
		waiter.setDaemon(true);
		creator.start();
		assertTrue(factoryEntered.await(5, TimeUnit.SECONDS));
		waiter.start();
		assertTrue(waiterStarted.await(5, TimeUnit.SECONDS));
		releaseFactory.countDown();
		creator.join(1_000);
		waiter.join(1_000);

		assertFalse(creator.isAlive());
		assertFalse(waiter.isAlive());
		assertNull(failure.get());
		assertEquals(1, factoryCalls.get());
		assertSame(expected, first.get());
		assertSame(expected, second.get());
		context.close();
	}

