	private static final class RecordingIteration implements CloseableIteration<BindingSet>, CooperativeCancellation {

		private final boolean accepted;
		private final RuntimeException cancellationFailure;
		private final Throwable closeFailure;
		private final AtomicInteger requestCount = new AtomicInteger();
		private final AtomicInteger closeCount = new AtomicInteger();

		private RecordingIteration(boolean accepted, RuntimeException cancellationFailure) {
			this(accepted, cancellationFailure, null);
		}

		private RecordingIteration(boolean accepted, RuntimeException cancellationFailure, Throwable closeFailure) {
			this.accepted = accepted;
			this.cancellationFailure = cancellationFailure;
			this.closeFailure = closeFailure;
		}

		private static RecordingIteration throwingOnClose(Throwable failure) {
			return new RecordingIteration(true, null, failure);
		}

		@Override
		public boolean requestCancellation() {
			requestCount.incrementAndGet();
			if (cancellationFailure != null) {
				throw cancellationFailure;
			}
			return accepted;
		}

		@Override
		public boolean hasNext() {
			return false;
		}

		@Override
		public BindingSet next() {
			throw new NoSuchElementException();
		}

		@Override
		public void remove() {
			throw new UnsupportedOperationException();
		}

		@Override
		public void close() {
			closeCount.incrementAndGet();
			if (closeFailure instanceof RuntimeException runtimeException) {
				throw runtimeException;
			}
			if (closeFailure instanceof Error error) {
				throw error;
			}
		}
	}

	private static final class SameFailureIteration implements CloseableIteration<BindingSet> {

		private final RuntimeException failure;
		private final AtomicInteger closeCount = new AtomicInteger();

		private SameFailureIteration(RuntimeException failure) {
			this.failure = failure;
		}

		@Override
		public boolean hasNext() {
			throw failure;
		}

		@Override
		public BindingSet next() {
			throw new NoSuchElementException();
		}

		@Override
		public void remove() {
			throw new UnsupportedOperationException();
		}

		@Override
		public void close() {
			closeCount.incrementAndGet();
			throw failure;
		}
	}

